# Factual dated fixed-horizon collections cashflow assessment.
collections_backtest<-function(forecasts,episodes,cashflows,actions,cashflow_coverage,discount_contract,design,uncertainty,cluster_resamples=NULL,confidence_level=.95,context=NULL){
 d<-.vb_design(design,context);rows<-.vb_records(forecasts,d);history<-.ex_read(if(inherits(episodes,'CalcResult'))episodes$value else episodes,'history_hash');cash<-.vr_rows(cashflows,'cashflows');action_rows<-.vr_rows(actions,'actions');coverage<-.vr_rows(cashflow_coverage,'cashflow_coverage');discount<-.ex_object(discount_contract,'discount_contract');if(!identical(history$evaluation_cutoff,d$evaluation_cutoff)).cr_error('COLLECTIONS_VALIDATION_CUTOFF','Episode history cutoff differs from design');currency<-.vb_string(d$currency,'validation currency');ctx<-.cr_result(NULL,'validation.context',context=context)$context;if(!is.null(ctx$currency)&&!identical(ctx$currency,currency)).cr_error('COLLECTIONS_VALIDATION_CURRENCY','Context and validation currencies differ');.vb_string(discount$reference,'discount reference');rate<-.vb_number(discount$annual_rate,'annual_rate');known<-.cr_data_date(discount$known_at,'discount known_at');if(!identical(discount$method,'flat_effective_annual')||!identical(discount$day_count,'ACT_365F')||rate<=-1||!identical(discount$currency,currency)).cr_error('COLLECTIONS_VALIDATION_DISCOUNT','Declare matched flat annual ACT_365F discount with rate > -1');if(any(vapply(rows,function(r)known>.cr_data_date(r$forecast_known_at,'forecast_known_at'),logical(1)))).cr_error('COLLECTIONS_VALIDATION_LOOKAHEAD','Discount unavailable at forecast');eps<-setNames(history$episodes,vapply(history$episodes,function(e)e$episode_id,character(1)));.ex_ids(lapply(cash,function(r)r$cashflow_id),'cashflow IDs',empty=TRUE);.ex_ids(lapply(action_rows,function(r)r$action_id),'action IDs',empty=TRUE);.ex_ids(lapply(coverage,function(r)r$episode_id),'cashflow coverage episode IDs',empty=TRUE);action_index<-setNames(action_rows,vapply(action_rows,function(r)r$action_id,character(1)));coverage_index<-setNames(coverage,vapply(coverage,function(r)r$episode_id,character(1)));cash_index<-list();cutoff<-.cr_data_date(d$evaluation_cutoff,'evaluation_cutoff')
 for(cashrow in cash){if(is.null(cashrow$episode_id)||!cashrow$episode_id%in%names(eps)||!cashrow$kind%in%c('REPAYMENT','RECOVERY','COST')||!identical(cashrow$currency,currency)).cr_error('COLLECTIONS_VALIDATION_CASH','Known episode/kind and matching currency required');.vb_number(cashrow$amount,'cash amount',0);at<-.cr_data_date(cashrow$occurred_at,'cash occurred_at');available<-.cr_data_date(cashrow$known_at,'cash known_at');if(available<at||at<.cr_data_date(eps[[cashrow$episode_id]]$started_at,'episode start')).cr_error('COLLECTIONS_VALIDATION_DATE','Cash knowledge follows occurrence in episode lineage');cash_index[[cashrow$episode_id]]<-c(cash_index[[cashrow$episode_id]],list(cashrow))}
 for(cov in coverage){start<-.cr_data_date(cov$observed_from,'cash coverage from');end<-.cr_data_date(cov$observed_through,'cash coverage through');available<-.cr_data_date(cov$known_at,'cash coverage known');if(!cov$episode_id%in%names(eps)||start>end||available<end).cr_error('COLLECTIONS_VALIDATION_COVERAGE','Valid known episode cash capture interval required')};for(a in action_rows){for(key in c('account_id','treatment_id','action_type')).vb_string(a[[key]],key);if(!a$stage%in%c('ASSIGNED','OFFERED','ACCEPTED','PERFORMED','CANCELLED')).cr_error('COLLECTIONS_VALIDATION_ACTION','Unknown action stage');if(.cr_data_date(a$known_at,'action known_at')<.cr_data_date(a$occurred_at,'action occurred_at')).cr_error('COLLECTIONS_VALIDATION_ACTION','Action knowledge precedes occurrence')}
 kinds<-c('REPAYMENT','RECOVERY','COST');keys<-c('discounted_repayment','discounted_recovery','discounted_cost','discounted_net','recovery_weighted_days');p<-y<-setNames(lapply(keys,function(k)rep(0,length(rows))),keys);eligible<-timing<-rep(FALSE,length(rows));weights<-rep(1,length(rows));groups<-character();traces<-exclusions<-list()
 value<-function(flows,asof){sums<-setNames(rep(0,3),kinds);recovery_mass<-weighted_days<-0;for(cashrow in flows){days<-as.numeric(.cr_data_date(cashrow$occurred_at,'cash date')-asof);factor<-exp(-log1p(rate)*days/365);amount<-cashrow$amount;sums[cashrow$kind]<-sums[cashrow$kind]+amount*factor;if(cashrow$kind=='RECOVERY'){recovery_mass<-recovery_mass+amount;weighted_days<-weighted_days+amount*days}};result<-list(discounted_repayment=unname(sums['REPAYMENT']),discounted_recovery=unname(sums['RECOVERY']),discounted_cost=unname(sums['COST']),discounted_net=unname(sums['REPAYMENT']+sums['RECOVERY']-sums['COST']),recovery_weighted_days=if(recovery_mass==0)NULL else weighted_days/recovery_mass);if(any(!is.finite(unlist(result)))).cr_error('COLLECTIONS_VALIDATION_NUMERICAL','Discounted flow exceeds finite range');result}
 for(i in seq_along(rows)){row<-rows[[i]];episode<-eps[[row$episode_id]];asof<-.cr_data_date(row$as_of,'as_of');end<-.cr_data_date(row$horizon_end,'horizon_end');weights[i]<-.vb_number(if(is.null(row$weight))1 else row$weight,'weight',0);if(is.null(episode)||!identical(row$account_id,episode$account_id)||asof<.cr_data_date(episode$started_at,'episode start')).cr_error('COLLECTIONS_VALIDATION_EPISODE','Forecast must belong to already-started account episode');if(length(episode$timeline)&&.cr_data_date(episode$timeline[[1]]$known_at,'episode first known')>.cr_data_date(row$forecast_known_at,'forecast_known_at')).cr_error('COLLECTIONS_VALIDATION_LOOKAHEAD','Episode onset unavailable at forecast');action<-action_index[[row$index_action_id]];if(is.null(action)||!identical(action$account_id,row$account_id)||!action$stage%in%c('ASSIGNED','OFFERED')||action$known_at>row$forecast_known_at||action$occurred_at>row$as_of).cr_error('COLLECTIONS_VALIDATION_ACTION','Known assignment/offer required, not eventual uptake');embedded<-Filter(function(a)identical(a$action_id,action$action_id),episode$actions);if(length(embedded)!=1||any(vapply(c('account_id','treatment_id','action_type','stage','occurred_at','known_at'),function(k)!identical(embedded[[1]][[k]],action[[k]]),logical(1)))).cr_error('COLLECTIONS_VALIDATION_ACTION','Assignment must match frozen episode-linked record');groups<-c(groups,action$action_type);projected<-.vr_rows(row$predicted_cashflows,'predicted_cashflows');.ex_ids(lapply(projected,function(c)c$cashflow_id),'predicted cashflow IDs',empty=TRUE);for(cashrow in projected){at<-.cr_data_date(cashrow$occurred_at,'predicted cash date');if(!cashrow$kind%in%kinds||!identical(cashrow$currency,currency)||at<asof||at>end).cr_error('COLLECTIONS_VALIDATION_FORECAST','Forecast cash kind/currency/date mismatch');.vb_number(cashrow$amount,'predicted amount',0)};actual<-Filter(function(cashrow){at<-.cr_data_date(cashrow$occurred_at,'cash date');asof<=at&&at<=min(end,cutoff)&&.cr_data_date(cashrow$known_at,'cash known')<=cutoff},cash_index[[row$episode_id]]);pv<-value(projected,asof);av<-value(actual,asof);cover<-coverage_index[[row$episode_id]];reason<-NULL;if(end>cutoff)reason<-'IMMATURE_HORIZON'else if(is.null(cover)||.cr_data_date(cover$known_at,'coverage known')>cutoff||.cr_data_date(cover$observed_from,'coverage from')>asof||.cr_data_date(cover$observed_through,'coverage through')<end)reason<-'INCOMPLETE_CASHFLOW_CAPTURE'else if(weights[i]==0)reason<-'ZERO_EVALUATION_WEIGHT'else eligible[i]<-TRUE;timing[i]<-eligible[i]&&!is.null(pv$recovery_weighted_days)&&!is.null(av$recovery_weighted_days);for(key in keys){p[[key]][i]<-if(is.null(pv[[key]]))0 else pv[[key]];y[[key]][i]<-if(is.null(av[[key]]))0 else av[[key]]};if(!is.null(reason))exclusions[[length(exclusions)+1]]<-list(prediction_id=row$prediction_id,reason=reason);traces[[length(traces)+1]]<-list(prediction_id=row$prediction_id,episode_id=row$episode_id,episode_status_at_cutoff=episode$status,index_action_id=action$action_id,treatment_id=action$treatment_id,action_type=action$action_type,predicted=pv,observed_known_to_cutoff=av,observed_cashflow_ids=lapply(actual,function(c)c$cashflow_id),complete_fixed_horizon=eligible[i],timing_applicability=if(timing[i])'APPLICABLE'else'NOT_APPLICABLE',timing_reason=if(timing[i])NULL else'NO_PAIRED_POSITIVE_RECOVERY_MASS_OR_INCOMPLETE_WINDOW')}
 calculate<-function(draw){group<-function(mask)setNames(lapply(keys,function(k).vb_errors(p[[k]],y[[k]],weights*draw*mask*(if(k=='recovery_weighted_days')timing else eligible))),keys);by_action<-setNames(lapply(sort(unique(groups)),function(g)group(groups==g)),sort(unique(groups)));if(!length(by_action))by_action<-structure(list(),names=character());list(overall=group(rep(1,length(rows))),by_action=by_action)};values<-calculate(rep(1,length(rows)));draws<-.vb_draws(uncertainty,cluster_resamples,rows,confidence_level);samples<-if(is.null(draws))NULL else lapply(draws,function(draw){m<-calculate(draw);flat<-list();for(k in keys)for(metric in c('bias','rmse'))flat[paste(k,metric,sep='/')]<-list(m$overall[[k]][[metric]]);for(g in names(m$by_action))for(k in keys)for(metric in c('bias','rmse'))flat[paste(g,k,metric,sep='/')]<-list(m$by_action[[g]][[k]][[metric]]);flat});status_counts<-as.list(table(vapply(rows,function(r)eps[[r$episode_id]]$status,character(1))));if(!length(status_counts))status_counts<-structure(list(),names=character());diagnostics<-list(discount_contract=discount,episode_history_hash=history$history_hash,cashflow_fingerprint=.cr_hash(cash),action_fingerprint=.cr_hash(action_rows),cashflow_coverage_fingerprint=.cr_hash(coverage),forecast_traces=traces,episode_status_counts=status_counts,estimand='FACTUAL_FIXED_HORIZON_CASHFLOWS',causal_action_effect_identified=FALSE,open_episodes_treated_as_closed=FALSE,cashflow_window='[forecast_as_of, horizon_end]',timing_estimand='UNDISCOUNTED_RECOVERY_AMOUNT_WEIGHTED_MEAN_DAYS_CONDITIONAL_ON_POSITIVE_PREDICTED_AND_OBSERVED_RECOVERY');.vb_result('collections_backtest',values,d,rows,exclusions,.vb_bands(samples,confidence_level),context,diagnostics,currency)
}
